const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('.nav');
menu?.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',String(open));nav.classList.toggle('open',open);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.focus();}});
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));let count=0;document.querySelectorAll('[data-category]').forEach(x=>{x.hidden=b.dataset.filter!=='all'&&x.dataset.category!==b.dataset.filter;if(!x.hidden)count++;});document.querySelector('#gallery-count').textContent=count+' photograph'+(count===1?'':'s');}));
const dialog=document.querySelector('.lightbox');let photoTrigger;
document.querySelectorAll('[data-photo]').forEach(b=>b.addEventListener('click',()=>{photoTrigger=b;document.querySelector('#large-photo').src=b.dataset.photo;document.querySelector('#large-photo').alt=b.querySelector('img').alt;document.querySelector('#large-caption').textContent=b.dataset.caption;dialog.showModal();}));
document.querySelector('[data-close]')?.addEventListener('click',()=>dialog.close());dialog?.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});dialog?.addEventListener('close',()=>photoTrigger?.focus());
const form=document.querySelector('#quote-form');
form?.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const f=new FormData(form);const postcode=String(f.get('postcode')).trim().toUpperCase();const post=form.elements.postcode;post.setCustomValidity('');if(!/^[A-Z]{1,2}\d[A-Z\d]?\s*\d[A-Z]{2}$/i.test(postcode)){post.setCustomValidity('Please enter a full UK postcode, such as NN1 1AA.');post.reportValidity();return;}const message=`Hello Leon,\n\nI would like a free quotation for ${f.get('service')}.\n\nName: ${String(f.get('name')).trim()}\nProperty postcode: ${postcode}\nEmail: ${f.get('email')}\nPhone: ${f.get('phone')||'Not provided'}\n\nProject details:\n${String(f.get('details')).trim()}\n\nPlease let me know the next steps. Thank you.`;document.querySelector('#quote-message').value=message;document.querySelector('#email-enquiry').href='mailto:NNPaving@gmail.com?subject='+encodeURIComponent('Free quote enquiry — '+postcode)+'&body='+encodeURIComponent(message);const r=document.querySelector('#quote-result');r.hidden=false;document.querySelector('#quote-status').textContent='Not sent yet. Open your email app, add any photographs and send to NNPaving@gmail.com.';r.focus();r.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'center'});});
form?.elements.postcode.addEventListener('input',()=>form.elements.postcode.setCustomValidity(''));
form?.addEventListener('input',()=>{document.querySelector('#quote-result').hidden=true;});
document.querySelector('#copy-enquiry')?.addEventListener('click',async()=>{const t=document.querySelector('#quote-message');try{await navigator.clipboard.writeText(t.value);document.querySelector('#quote-status').textContent='Copied. Paste into an email addressed to NNPaving@gmail.com. Your enquiry has not been sent.';}catch{t.focus();t.select();document.querySelector('#quote-status').textContent='Select and copy the message above, then paste it into your email service.'}});
